      const sourceTexts = Array.isArray(rawTexts) ? rawTexts : [rawTexts];
      const rows = sourceTexts.map((value, sourceIndex) => ({ sourceIndex, text: prepareEmbeddingInput(value, purpose, cfg) })).filter(row => row.text);
