      vectorComparable,
      profileComparable: compatibility.profileComparable,
      legacyVector: compatibility.legacy,
      providerComparable,
      modelComparable,
      cosine,
      currentSemantic,
      previousVectorComparable,
      previousTurnCosine,
      previousSemantic,
