    const hasSemanticNumberSupport = c.keywordOverlap > 0 || c.nameOverlap > 0 || c.entityAnchor > 0 || c.quote > 0;
    if (c.numberOverlap > 0 && hasSemanticNumberSupport) reasons.push('number_context');
